var image_save_msg='You are not allowed to save images!';var no_menu_msg='Context Menu disabled!';var smessage="";function disableEnterKey(e){var elemtype=e.target.tagName;elemtype=elemtype.toUpperCase();if(elemtype=="TEXT"||elemtype=="TEXTAREA"||elemtype=="INPUT"||elemtype=="PASSWORD"||elemtype=="SELECT"||elemtype=="OPTION"||elemtype=="EMBED"){elemtype='TEXT'}
if(e.ctrlKey){var key;if(window.event)
key=window.event.keyCode;else key=e.which;if(elemtype!='TEXT'&&(key==97||key==65||key==67||key==99||key==88||key==120||key==26||key==85||key==86||key==83||key==43||key==73)){if(wccp_free_iscontenteditable(e))return!0;show_wpcp_message('You are not allowed to copy content or view source');return!1}else return!0}}
function wccp_free_iscontenteditable(e){var e=e||window.event;var target=e.target||e.srcElement;var elemtype=e.target.nodeName;elemtype=elemtype.toUpperCase();var iscontenteditable="false";if(typeof target.getAttribute!="undefined")iscontenteditable=target.getAttribute("contenteditable");var iscontenteditable2=!1;if(typeof target.isContentEditable!="undefined")iscontenteditable2=target.isContentEditable;if(target.parentElement.isContentEditable)iscontenteditable2=!0;if(iscontenteditable=="true"||iscontenteditable2==!0){if(typeof target.style!="undefined")target.style.cursor="text";return!0}}
function disable_copy(e){var e=e||window.event;var elemtype=e.target.tagName;elemtype=elemtype.toUpperCase();if(elemtype=="TEXT"||elemtype=="TEXTAREA"||elemtype=="INPUT"||elemtype=="PASSWORD"||elemtype=="SELECT"||elemtype=="OPTION"||elemtype=="EMBED"){elemtype='TEXT'}
if(wccp_free_iscontenteditable(e))return!0;var isSafari=/Safari/.test(navigator.userAgent)&&/Apple Computer/.test(navigator.vendor);var checker_IMG='';if(elemtype=="IMG"&&checker_IMG=='checked'&&e.detail>=2){show_wpcp_message(alertMsg_IMG);return!1}
if(elemtype!="TEXT"){if(smessage!==""&&e.detail==2)
show_wpcp_message(smessage);if(isSafari)
return!0;else return!1}}
function disable_copy_ie(){var e=e||window.event;var elemtype=window.event.srcElement.nodeName;elemtype=elemtype.toUpperCase();if(wccp_free_iscontenteditable(e))return!0;if(elemtype=="IMG"){show_wpcp_message(alertMsg_IMG);return!1}
if(elemtype!="TEXT"&&elemtype!="TEXTAREA"&&elemtype!="INPUT"&&elemtype!="PASSWORD"&&elemtype!="SELECT"&&elemtype!="OPTION"&&elemtype!="EMBED"){return!1}}
function reEnable(){return!0}
document.onkeydown=disableEnterKey;document.onselectstart=disable_copy_ie;if(navigator.userAgent.indexOf('MSIE')==-1){document.onmousedown=disable_copy;document.onclick=reEnable}
function disableSelection(target){if(typeof target.onselectstart!="undefined")
target.onselectstart=disable_copy_ie;else if(typeof target.style.MozUserSelect!="undefined"){target.style.MozUserSelect="none"}else target.onmousedown=function(){return!1}
target.style.cursor="default"}
window.onload=function(){disableSelection(document.body)};var onlongtouch;var timer;var touchduration=1000;var elemtype="";function touchstart(e){var e=e||window.event;var target=e.target||e.srcElement;elemtype=window.event.srcElement.nodeName;elemtype=elemtype.toUpperCase();if(!wccp_pro_is_passive())e.preventDefault();if(!timer){timer=setTimeout(onlongtouch,touchduration)}}
function touchend(){if(timer){clearTimeout(timer);timer=null}
onlongtouch()}
onlongtouch=function(e){if(elemtype!="TEXT"&&elemtype!="TEXTAREA"&&elemtype!="INPUT"&&elemtype!="PASSWORD"&&elemtype!="SELECT"&&elemtype!="EMBED"&&elemtype!="OPTION"){if(window.getSelection){if(window.getSelection().empty){window.getSelection().empty()}else if(window.getSelection().removeAllRanges){window.getSelection().removeAllRanges()}}else if(document.selection){document.selection.empty()}
return!1}};document.addEventListener("DOMContentLiteSpeedLoaded",function(event){window.addEventListener("touchstart",touchstart,!1);window.addEventListener("touchend",touchend,!1)});function wccp_pro_is_passive(){var cold=!1,hike=function(){};try{const object1={};var aid=Object.defineProperty(object1,'passive',{get(){cold=!0}});window.addEventListener('test',hike,aid);window.removeEventListener('test',hike,aid)}catch(e){}
return cold}

body.script:
/*!
WeddingPress Custom Nama Tamu (WDPCNT) & URL Normalizer
============================================

Description: 
WeddingPress Custom Nama Tamu (WDPCNT) adalah script JavaScript yang digunakan untuk mengganti teks "Tamu Undangan" pada elemen dengan class `namatamu` berdasarkan parameter yang ada di URL. 
Script ini mendukung beberapa parameter seperti `to`, `dear`, dan `kepada` untuk menyesuaikan nama penerima undangan. Serta dilengkapi dengan engine URL Normalizer untuk memperbaiki karakter khusus (&) secara otomatis.

Author: Andy dari WeddingPress
Website: https://weddingpress.net
Version: 1.1 (2025/03/01)
License: Anda diizinkan menggunakan script ini pada website Anda dan proyek klien. Tidak diperbolehkan menjual, membagikan, menempatkan codenya ditemplate yang dijual atau mendistribusikan ulang tanpa izin.
Copyright: © 2025 WeddingPress. All rights reserved.

Note:
Pastikan untuk teks 'Tamu Undangan' css classesnya sudah terisi: 'namatamu'
 */
(function(){'use strict';const config={selector:'.namatamu',urlParams:['to','dear','kepada'],defaultText:'Tamu Undangan'};var rawSearch=location.search;if(rawSearch.indexOf('?')!==-1){var params=new URLSearchParams(rawSearch);var needsRedirect=!1;for(const key of config.urlParams){if(rawSearch.indexOf('?'+key+'=')!==-1||rawSearch.indexOf('&'+key+'=')!==-1){var rawName=params.get(key);if(rawName!==null){var decoded=rawName.replace(/&/gi,'&').replace(/&/gi,'&').replace(/&/gi,'&').replace(/'/gi,"'").replace(/'/gi,"'").replace(/"/gi,'"').replace(/"/gi,'"');if(rawName!==decoded||rawSearch.indexOf('&'+key+'=')!==-1){params.set(key,decoded);needsRedirect=!0}}}}
if(needsRedirect){var newSearch='?'+params.toString();if(newSearch!==rawSearch){location.replace(location.pathname+newSearch);return}}}
function getRecipientName(params,keys){for(const key of keys){const value=params.get(key);if(value&&value.trim()){return value.trim()}}
return''}
function escapeRegExp(string){return string.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')}
function replaceTextInNode(node,searchValue,replaceValue){if(node.nodeType===1||node.nodeType===11){node.childNodes.forEach(child=>{if(child.nodeType===3){const safeSearchValue=escapeRegExp(searchValue);const regex=new RegExp(safeSearchValue,'gi');var txt=document.createElement('textarea');txt.innerHTML=replaceValue;var decodedReplaceValue=txt.value;child.textContent=child.textContent.replace(regex,decodedReplaceValue)}else{replaceTextInNode(child,searchValue,replaceValue)}})}}
function wdpDisplayGuestName(){const params=new URLSearchParams(window.location.search);const recipient=getRecipientName(params,config.urlParams);const targets=document.querySelectorAll(config.selector);if(targets.length===0)return;targets.forEach(element=>{if(recipient){replaceTextInNode(element,config.defaultText,recipient)}else{if(!element.textContent.trim()){element.textContent=config.defaultText}}})}
if(document.readyState==='loading'){document.addEventListener('DOMContentLiteSpeedLoaded',wdpDisplayGuestName)}else{wdpDisplayGuestName()}})()
